        removeHabit(item.dataset.id);
      }
    });

    document.addEventListener('visibilitychange', function () {
      if (!document.hidden) checkDayChange();
    });

    window.addEventListener('focus', checkDayChange);

    window.setInterval(checkDayChange, 60000);

    window.addEventListener('storage', function (event) {
      if (event.key !== STORAGE_KEY) return;
      habits = readStore();
      render();
    });
  }

  function start() {
    els.today = document.getElementById('today');
    els.listSection = document.getElementById('habit-list-section');
    els.list = document.getElementById('habit-list');
    els.emptyNote = document.getElementById('empty-note');
    els.summary = document.getElementById('streak-summary');
    els.form = document.getElementById('habit-form');
    els.input = document.getElementById('habit-name');

    if (!els.list || !els.emptyNote || !els.summary || !els.form || !els.input) {
      return;
    }

    els.status = createStatusRegion();
    todayKey = keyFor(new Date());
    habits = readStore();

    if (!storageWorks) showStorageWarning();

    bind();
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();

