  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  column-gap: clamp(0.75rem, 3vw, 1.125rem);
  padding: 0.75rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  transition: background-color 150ms ease, border-color 150ms ease;
}

.habit-item:hover {
  border-color: var(--line-strong);
}

/* Ticked today: the whole row turns the colour of a finished day. */
.habit-item.is-ticked {
  background: var(--green-wash);
  border-color: var(--green-edge);
}

/* The daily tick box */
.habit-tick {
  width: clamp(2.75rem, 10vw, 3.25rem);
  height: clamp(2.75rem, 10vw, 3.25rem);
  display: inline-grid;
  place-items: center;
  padding: 0;
  color: transparent; /* hides the check inside the SVG until it is ticked */
  background: var(--surface);
  border: 2px solid var(--line-ui);
  border-radius: 12px;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.habit-tick:hover {
  background: var(--green-wash);
  border-color: var(--green);
}

.habit-tick:active {
  background: var(--green-wash);
  border-color: var(--green-deep);
}

.habit-tick[aria-pressed="true"] {
  color: #ffffff;
  background: var(--green);
  border-color: var(--green);
}

.habit-tick[aria-pressed="true"]:hover {
  background: var(--green-deep);
  border-color: var(--green-deep);
}

.habit-tick[aria-pressed="true"]:active {
  background: var(--green-deep);
  border-color: var(--green-deep);
  transform: translateY(1px);
}

.tick-mark {
  width: 1.375rem;
  height: 1.375rem;
  display: block;
}

.habit-name {
  min-width: 0;
  font-size: var(--text-body);
  font-weight: 550;
  letter-spacing: -0.01em;
  overflow-wrap: break-word;
}

/* Streak badge in each row: quiet while the habit waits, solid clay once the
   day is ticked, because the streak is the result of the tick. */
.habit-streak {
  padding: 0.3rem 0.6rem;
  font-size: var(--text-micro);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--ink-faint);
  background: var(--surface-soft);
  border: 1px solid var(--line);
  border-radius: 999px;
}

.habit-item.is-ticked .habit-streak {
  color: #ffffff;
  background: var(--accent);
  border-color: var(--accent);
}

.habit-remove {
  padding: 0.35rem 0.5rem;
  font: inherit;
  font-size: var(--text-micro);
  font-weight: 600;
  color: var(--ink-faint);
  background: none;
  border: 1px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: color 150ms ease, background-color 150ms ease, border-color 150ms ease;
}

.habit-remove:hover {
  color: var(--danger);
  background: var(--danger-wash);
  border-color: var(--danger-edge);
}

.habit-remove:active {
  color: var(--danger);
  background: var(--danger-wash);
  transform: translateY(1px);
}

/* Empty list -------------------------------------------------------------- */

.empty-note {
  margin: 0;
  padding: 0.9rem 1rem;
  font-size: var(--text-small);
  color: var(--ink-soft);
  background: var(--surface-soft);
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-sm);
}

.empty-note[hidden] {
  display: none;
}

/* Streak summary ---------------------------------------------------------- */

.streak-note {
  margin-bottom: 0.35rem;
  font-size: var(--text-small);
  color: var(--ink-soft);
}

.streak-summary {
  display: grid;
}

.streak-line {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 1rem;
  padding: 0.6rem 0.15rem;
  font-size: var(--text-small);
  border-bottom: 1px solid var(--line);
}

.streak-line:last-child {
  border-bottom: 0;
}

.streak-name {
  min-width: 0;
  color: var(--ink-soft);
  overflow-wrap: break-word;
}

.streak-value {
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--ink-faint);
}

.streak-line.has-streak .streak-name {
  color: var(--ink);
  font-weight: 550;
}

.streak-line.has-streak .streak-value {
  padding: 0.15rem 0.55rem;
  color: var(--accent-deep);
  background: var(--accent-wash);
  border-radius: 999px;
}

/* Add form ---------------------------------------------------------------- */

.habit-form {
  display: grid;
  gap: 0.5rem;
}

.field-label {
  font-size: var(--text-small);
  font-weight: 650;
  letter-spacing: -0.005em;
}

.field-input {
  width: 100%;
  min-width: 0;
  padding: 0.85rem 1rem;
  font: inherit;
  font-size: var(--text-body);
  color: var(--ink);
  background: var(--surface);
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius-sm);
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.field-input:hover {
  border-color: var(--line-ui);
}

.field-input:focus {
  outline: none;
  border-color: var(--green);
  box-shadow: 0 0 0 3px var(--green-wash);
}

.field-hint {
  font-size: var(--text-small);
  line-height: 1.45;
  color: var(--ink-soft);
}

.add-button {
  justify-self: start;
  margin-top: 0.25rem;
  padding: 0.8rem 1.4rem;
  font: inherit;
  font-size: var(--text-body);
  font-weight: 650;
  letter-spacing: -0.01em;
  color: #ffffff;
  background: var(--accent);
  border: 1.5px solid var(--accent);
  border-radius: 12px;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(22, 32, 26, 0.12);
  transition: background-color 150ms ease, border-color 150ms ease, transform 120ms ease, box-shadow 150ms ease;
}

.add-button:hover {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
  box-shadow: 0 4px 12px -6px rgba(22, 32, 26, 0.5);
}

.add-button:active {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
  transform: translateY(1px);
  box-shadow: none;
}

/* Footer and notices ------------------------------------------------------ */

.footer {
  max-width: 34rem;
  padding-top: 1rem;
  font-size: var(--text-small);
  line-height: 1.6;
  color: var(--ink-soft);
  border-top: 1px solid var(--line-strong);
}

.storage-warning {
  margin-bottom: 0.75rem;
  padding: 0.8rem 1rem;
  font-size: var(--text-small);
  color: var(--danger);
  background: var(--danger-wash);
  border: 1px solid var(--danger-edge);
  border-radius: var(--radius-sm);
}

.notice {
  width: min(100% - 2.25rem, 40rem);
  margin: 1.5rem auto 0;
  padding: 0.9rem 1rem;
  font-size: var(--text-small);
  color: var(--danger);
  background: var(--danger-wash);
  border: 1px solid var(--danger-edge);
  border-radius: var(--radius-sm);
}

/* Skip link and screen reader text ---------------------------------------- */

.skip-link {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 10;
  padding: 0.6rem 1rem;
  font-size: var(--text-small);
  font-weight: 650;
  color: var(--paper);
  background: var(--ink);
  border-radius: var(--radius-sm);
  text-decoration: none;
  transform: translateY(-200%);
  transition: transform 150ms ease;
}

.skip-link:focus,
.skip-link:focus-visible {
  transform: none;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Focus --------------------------------------------------------------- */

a:focus-visible,
button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 8px;
}

/* Phone layout: the row recomposes into a tick box beside a name, with the
   streak badge and the remove action on a second line, and the action button
   stretching to reach. */
@media (max-width: 34rem) {
  .page {
    width: 100%;
    padding-inline: 1rem;
    padding-block: 1.5rem 2rem;
    gap: 1.5rem;
  }

  .board {
    gap: 1.5rem;
  }

  .today {
    font-size: clamp(2.25rem, 12vw, 3rem);
  }

  .panel {
    padding: 1rem;
    border-radius: var(--radius-sm);
  }

  .panel.streaks {
    padding: 0;
  }

  .habit-item {
    grid-template-columns: auto minmax(0, 1fr) auto;
    grid-template-areas:
      "tick name name"
      "tick streak remove";
    column-gap: 0.75rem;
    row-gap: 0.6rem;
  }

  .habit-tick {
    grid-area: tick;
    align-self: center;
  }

  .habit-name {
    grid-area: name;
  }

  .habit-streak {
    grid-area: streak;
    justify-self: start;
  }

  .habit-remove {
    grid-area: remove;
    justify-self: end;
  }

  .add-button {
    justify-self: stretch;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms;
    animation-duration: 0.01ms;
  }
}

