/* Habit tracker: add and remove habits, tick a habit for today, count streaks,
   keep every habit and ticked date under one local storage key, and remember a
   light or dark theme choice in this browser. */
(function () {
  'use strict';

  const STORAGE_KEY = 'habit-tracker:v1';
  const THEME_KEY = 'habit-tracker:theme';
  const NAME_LIMIT = 60;
  const DATE_KEY = /^\d{4}-\d{2}-\d{2}$/;

  const els = {
    today: null,
    listSection: null,
    list: null,
    emptyNote: null,
    summary: null,
    form: null,
    input: null,
    status: null
  };

  let habits = [];
  let todayKey = '';
  let storageWorks = true;
  let warningShown = false;
  let themeChoice = null;
  let themeControl = null;

  /* Dates ------------------------------------------------------------------ */

  function keyFor(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return year + '-' + month + '-' + day;
  }

  /* Noon keeps day arithmetic away from daylight saving shifts. */
  function noonToday() {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12, 0, 0, 0);
  }

  function longDate() {
    return new Date().toLocaleDateString(undefined, {
      weekday: 'long',
      day: 'numeric',
      month: 'long'
    });
  }

  function isDateKey(value) {
    return typeof value === 'string' && DATE_KEY.test(value);
  }

  function dayCount(number) {
    return number + (number === 1 ? ' day' : ' days');
  }

  /* Streak counts the run of ticked days that ends today, so a habit that is not
     ticked today reads zero until it is ticked. */
  function streakEndingToday(ticks) {
    const ticked = new Set(ticks);
    let streak = 0;
    const cursor = noonToday();
    while (ticked.has(keyFor(cursor))) {
      streak += 1;
      cursor.setDate(cursor.getDate() - 1);
    }
    return streak;
  }

  /* Theme --------------------------------------------------------------------
     The habits and their ticked dates live under one key. The light or dark
     choice is not habit data, so it sits under its own small key and comes back
     on the next visit. With no saved choice the page follows the system. */

  function systemTheme() {
    if (window.matchMedia) {
      try {
        if (window.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark';
      } catch (error) {
        /* fall through to light */
      }
    }
    return 'light';
  }

  function readTheme() {
    let stored = null;
    try {
      stored = window.localStorage.getItem(THEME_KEY);
    } catch (error) {
      stored = null;
    }
    return stored === 'light' || stored === 'dark' ? stored : null;
  }

  function saveTheme(theme) {
    try {
      window.localStorage.setItem(THEME_KEY, theme);
    } catch (error) {
      /* The choice still applies to this visit. */
    }
  }

  function currentTheme() {
    return themeChoice === 'light' || themeChoice === 'dark' ? themeChoice : systemTheme();
  }

  function themeLabel(theme) {
    return theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme';
  }

  function paintTheme() {
    const theme = currentTheme();
    const dark = theme === 'dark';

    document.documentElement.setAttribute('data-theme', theme);
    document.documentElement.style.colorScheme = theme;

    if (!themeControl) return;

    const label = themeLabel(theme);
    themeControl.setAttribute('aria-pressed', dark ? 'true' : 'false');

    /* A switch written into the page keeps its own markup and only takes the
       label when it is plain text. A switch this script made is plain text. */
    if (themeControl.children.length === 0) {
      themeControl.textContent = label;
    } else {
      themeControl.setAttribute('aria-label', label);
    }
  }

  function findThemeControl() {
    const marked = document.querySelector('[data-theme-toggle], #theme-toggle, .theme-toggle');
    if (marked) return marked;

    const masthead = document.querySelector('.masthead');
    if (!masthead) return null;

    const buttons = masthead.querySelectorAll('button');
    for (let i = 0; i < buttons.length; i += 1) {
      const text = (buttons[i].textContent || '') + ' ' + (buttons[i].getAttribute('aria-label') || '');
      if (/theme|dark|light/i.test(text)) return buttons[i];
    }
    return null;
  }

  function themeStylesExist() {
    try {
      const sheets = document.styleSheets;
      for (let i = 0; i < sheets.length; i += 1) {
        const rules = sheets[i].cssRules;
        if (!rules) continue;
        for (let j = 0; j < rules.length; j += 1) {
          const selector = rules[j].selectorText;
          if (selector && selector.indexOf('theme-toggle') !== -1) return true;
        }
      }
    } catch (error) {
      /* A sheet we cannot read is treated as styled. */
      return true;
    }
    return false;
  }

  function createThemeControl() {
    const host =
      document.querySelector('.masthead') ||
      document.querySelector('.page') ||
      document.body;
    if (!host) return null;

    const button = document.createElement('button');
    button.type = 'button';
    button.id = 'theme-toggle';
    button.className = 'theme-toggle';
    button.setAttribute('data-theme-toggle', '');
    host.appendChild(button);

    /* Plain fallback so the switch stays readable and clickable if the
       stylesheet carries no rule for it. */
    if (!themeStylesExist()) {
      button.style.cssText =
        'font:inherit;color:inherit;background:none;border:1px solid currentColor;' +
        'border-radius:999px;padding:0.45em 1em;cursor:pointer;';
    }
    return button;
  }

  function toggleTheme() {
    themeChoice = currentTheme() === 'dark' ? 'light' : 'dark';
    saveTheme(themeChoice);
    paintTheme();
    announce(themeChoice === 'dark' ? 'Dark theme on.' : 'Light theme on.');
  }

  function watchSystemTheme() {
    if (!window.matchMedia) return;
    const query = window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = function () {
      if (themeChoice === null) paintTheme();
    };
    if (typeof query.addEventListener === 'function') {
      query.addEventListener('change', onChange);
    } else if (typeof query.addListener === 'function') {
      query.addListener(onChange);
    }
  }

  /* Storage ---------------------------------------------------------------- */

  function makeId() {
    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
      return window.crypto.randomUUID();
    }
    return 'h' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function cleanHabit(entry) {
    if (!entry || typeof entry !== 'object') return null;
    const name = typeof entry.name === 'string' ? entry.name.trim().slice(0, NAME_LIMIT) : '';
    if (!name) return null;
    const rawTicks = Array.isArray(entry.ticks) ? entry.ticks.filter(isDateKey) : [];
    const ticks = Array.from(new Set(rawTicks)).sort();
    const id = typeof entry.id === 'string' && entry.id ? entry.id : makeId();
    return { id: id, name: name, ticks: ticks };
  }

  function readStore() {
    let raw = null;
    try {
      raw = window.localStorage.getItem(STORAGE_KEY);
    } catch (error) {
      storageWorks = false;
      return [];
    }
    if (!raw) return [];

    let parsed = null;
    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      return [];
    }

    let list = [];
    if (Array.isArray(parsed)) {
      list = parsed;
    } else if (parsed && Array.isArray(parsed.habits)) {
      list = parsed.habits;
    }

    return list.map(cleanHabit).filter(Boolean);
  }

  function save() {
    if (!storageWorks) return false;
    const payload = {
      version: 1,
      habits: habits.map(function (habit) {
        return { id: habit.id, name: habit.name, ticks: habit.ticks.slice() };
      })
    };
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
      return true;
    } catch (error) {
      storageWorks = false;
      showStorageWarning();
      return false;
    }
  }

  function showStorageWarning() {
    if (warningShown || !els.listSection || !els.list) return;
    warningShown = true;
    const note = document.createElement('p');
    note.className = 'storage-warning';
    note.setAttribute('role', 'alert');
    note.textContent =
      'This browser will not let the page save. Your habits work while the page stays open, but they will be gone after a reload.';
    els.listSection.insertBefore(note, els.list);
  }

  /* Markup ----------------------------------------------------------------- */

  function createStatusRegion() {
    const status = document.createElement('p');
    status.className = 'visually-hidden';
    status.setAttribute('role', 'status');
    status.setAttribute('aria-live', 'polite');
    status.style.cssText =
      'position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;';
    document.body.appendChild(status);
    return status;
  }

  function announce(message) {
    if (!els.status) return;
    els.status.textContent = message;
  }

  function buildTickButton(habit, ticked) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'habit-tick';
    button.dataset.action = 'tick';
    button.setAttribute('aria-pressed', ticked ? 'true' : 'false');
    button.setAttribute('aria-label', 'Tick ' + habit.name + ' for today');
    button.innerHTML =
      '<svg class="tick-mark" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false">' +
      '<path d="M4 12.5 9.5 18 20 6.5" fill="none" stroke="currentColor" stroke-width="2.5" ' +
      'stroke-linecap="round" stroke-linejoin="round"></path></svg>';
    return button;
  }

  function buildRow(habit) {
    const ticked = habit.ticks.indexOf(todayKey) !== -1;
    const streak = streakEndingToday(habit.ticks);

    const item = document.createElement('li');
    item.className = 'habit-item' + (ticked ? ' is-ticked' : '');
    item.dataset.id = habit.id;

    const name = document.createElement('span');
    name.className = 'habit-name';
    name.textContent = habit.name;

    const streakEl = document.createElement('span');
    streakEl.className = 'habit-streak';
    streakEl.textContent = dayCount(streak);

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'habit-remove';
    remove.dataset.action = 'remove';
    remove.setAttribute('aria-label', 'Remove ' + habit.name);
    remove.textContent = 'Remove';

    item.appendChild(buildTickButton(habit, ticked));
    item.appendChild(name);
    item.appendChild(streakEl);
    item.appendChild(remove);
    return item;
  }

  function render(focusSpec) {
    if (els.today) els.today.textContent = longDate();
    renderList();
    renderStreaks();
    renderEmptyNote();
    restoreFocus(focusSpec);
  }

  function renderList() {
    els.list.textContent = '';
    const fragment = document.createDocumentFragment();
    habits.forEach(function (habit) {
      fragment.appendChild(buildRow(habit));
    });
    els.list.appendChild(fragment);
  }

  function renderStreaks() {
    els.summary.textContent = '';

    if (!habits.length) {
      const empty = document.createElement('p');
      empty.className = 'streak-line';
      empty.textContent = 'No habits to count yet.';
      els.summary.appendChild(empty);
      return;
    }

    const rows = habits
      .map(function (habit) {
        return { id: habit.id, name: habit.name, streak: streakEndingToday(habit.ticks) };
      })
      .sort(function (a, b) {
        if (b.streak !== a.streak) return b.streak - a.streak;
        return a.name.localeCompare(b.name);
      });

    rows.forEach(function (row) {
      const line = document.createElement('p');
      line.className = 'streak-line' + (row.streak > 0 ? ' has-streak' : '');

      const name = document.createElement('span');
      name.className = 'streak-name';
      name.textContent = row.name;

      const value = document.createElement('span');
      value.className = 'streak-value';
      value.textContent = dayCount(row.streak);

      line.appendChild(name);
      line.appendChild(value);
      els.summary.appendChild(line);
    });
  }

  function renderEmptyNote() {
    const empty = habits.length === 0;
    els.emptyNote.hidden = !empty;
    els.emptyNote.style.display = empty ? '' : 'none';
  }

  function restoreFocus(spec) {
    if (!spec) return;

    if (spec.id) {
      const items = Array.prototype.slice.call(els.list.children);
      const item = items.filter(function (node) {
        return node.dataset.id === spec.id;
      })[0];

      if (item) {
        const selector = spec.action === 'remove' ? '.habit-remove' : '.habit-tick';
        const button = item.querySelector(selector);
        if (button) {
          button.focus();
          return;
        }
      }
    }

    if (spec.fallback && typeof spec.fallback.focus === 'function') {
      spec.fallback.focus();
    }
  }

  /* Actions ---------------------------------------------------------------- */

  function findById(id) {
    return habits.filter(function (item) {
      return item.id === id;
    })[0] || null;
  }

  function toggleToday(id) {
    const habit = findById(id);
    if (!habit) return;

    const index = habit.ticks.indexOf(todayKey);
    if (index === -1) {
      habit.ticks.push(todayKey);
    } else {
      habit.ticks.splice(index, 1);
    }
    habit.ticks.sort();

    save();
    render({ id: id, action: 'tick' });

    if (index === -1) {
      announce(habit.name + ' ticked for today. Streak is ' + dayCount(streakEndingToday(habit.ticks)) + '.');
    } else {
      announce(habit.name + ' unticked for today. Streak is ' + dayCount(streakEndingToday(habit.ticks)) + '.');
    }
  }

  function removeHabit(id) {
    const index = habits.findIndex(function (item) {
      return item.id === id;
    });
    if (index === -1) return;

    const removed = habits[index];
    habits.splice(index, 1);
    save();

    const next = habits[index] || habits[index - 1] || null;
    if (next) {
      render({ id: next.id, action: 'tick' });
    } else {
      render({ fallback: els.input });
    }

    announce(removed.name + ' removed.');
  }

  function addHabit(rawName) {
    const name = String(rawName).replace(/\s+/g, ' ').trim().slice(0, NAME_LIMIT);

    if (!name) {
      els.input.value = '';
      els.input.focus();
      announce('Type a habit name first.');
      return;
    }

    const duplicate = habits.filter(function (item) {
      return item.name.toLowerCase() === name.toLowerCase();
    })[0];

    if (duplicate) {
      els.input.value = '';
      announce('You already track ' + duplicate.name + '.');
      return;
    }

    const habit = { id: makeId(), name: name, ticks: [] };
    habits.push(habit);
    save();
    els.input.value = '';
    render({ id: habit.id, action: 'tick' });
    announce(name + ' added. Tick it once you have done it today.');
  }

  /* Wiring ----------------------------------------------------------------- */

  function checkDayChange() {
    const current = keyFor(new Date());
    if (current !== todayKey) {
      todayKey = current;
      render();
    }
  }

  function bind() {
    if (themeControl) {
      themeControl.addEventListener('click', toggleTheme);
    }

    els.form.addEventListener('submit', function (event) {
      event.preventDefault();
      addHabit(els.input.value);
    });

    els.list.addEventListener('click', function (event) {
      const target = event.target;
      if (!target || typeof target.closest !== 'function') return;
      const button = target.closest('button[data-action]');
      if (!button || !els.list.contains(button)) return;

      const item = button.closest('.habit-item');
      if (!item || !item.dataset.id) return;

      if (button.dataset.action === 'tick') {
        toggleToday(item.dataset.id);
      } else if (button.dataset.action === 'remove') {
        removeHabit(item.dataset.id);
      }
    });

    document.addEventListener('visibilitychange', function () {
      if (!document.hidden) checkDayChange();
    });

    window.addEventListener('focus', checkDayChange);

    window.setInterval(checkDayChange, 60000);

    window.addEventListener('storage', function (event) {
      if (event.key === STORAGE_KEY) {
        habits = readStore();
        render();
      } else if (event.key === THEME_KEY) {
        themeChoice = readTheme();
        paintTheme();
      }
    });
  }

  function start() {
    themeChoice = readTheme();
    themeControl = findThemeControl() || createThemeControl();
    paintTheme();
    watchSystemTheme();

    els.today = document.getElementById('today');
    els.listSection = document.getElementById('habit-list-section');
    els.list = document.getElementById('habit-list');
    els.emptyNote = document.getElementById('empty-note');
    els.summary = document.getElementById('streak-summary');
    els.form = document.getElementById('habit-form');
    els.input = document.getElementById('habit-name');

    if (!els.list || !els.emptyNote || !els.summary || !els.form || !els.input) {
      return;
    }

    els.status = createStatusRegion();
    todayKey = keyFor(new Date());
    habits = readStore();

    if (!storageWorks) showStorageWarning();

    bind();
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();

/* ==========================================================================
   Habit tracker — layout and look
   A single warm paper column: the day as the largest thing on the screen, a
   list of habit rows each with a big tick box, a quiet streak list, and a
   tinted add form. One signature green for a ticked day, one clay accent for
   the main action and the streak result.
   A light and a dark theme share the same tokens, so every control, hover,
   press and focus state follows the switch the masthead carries.
   Everything is drawn with CSS and the inline SVG that app.js writes into each
   tick button. There are no image files.
   ========================================================================== */

:root {
  color-scheme: light;

  /* Paper and ink, all tinted toward the green of a ticked day */
  --paper: #f2eee3;
  --paper-line: rgba(46, 107, 74, 0.07);
  --glow: rgba(163, 89, 26, 0.09);
  --surface: #fbf9f2;
  --surface-soft: #f6f3e9;
  --ink: #16201a;
  --ink-soft: #4f5c53;
  --ink-faint: #5f6d62;
  --line: #ded8c8;
  --line-strong: #c6bfa9;
  --line-ui: #6b7a70;

  /* Signature hue: the green of a ticked day. "Deep" means further from the
     surface, so it turns lighter when the page turns dark. */
  --green: #2e6b4a;
  --green-deep: #1f4f36;
  --green-wash: rgba(46, 107, 74, 0.1);
  --green-edge: rgba(46, 107, 74, 0.3);

  /* Accent: the main action, and the streak that comes out of it */
  --accent: #a3591a;
  --accent-deep: #83450f;
  --accent-wash: rgba(163, 89, 26, 0.14);

  /* Trouble */
  --danger: #9a3421;
  --danger-wash: rgba(154, 52, 33, 0.1);
  --danger-edge: rgba(154, 52, 33, 0.32);

  /* Words that sit on a solid green or clay fill */
  --on-solid: #ffffff;

  --focus: #16201a;
  --shadow-card: 0 1px 2px rgba(22, 32, 26, 0.05), 0 14px 28px -22px rgba(22, 32, 26, 0.45);
  --shadow-button: 0 1px 2px rgba(22, 32, 26, 0.12);
  --shadow-button-hover: 0 4px 12px -6px rgba(22, 32, 26, 0.5);

  --radius: 16px;
  --radius-sm: 10px;

  --font: "Avenir Next", "Segoe UI Variable Display", "Segoe UI", "Helvetica Neue", system-ui, sans-serif;
  --text-display: clamp(3.25rem, 1.75rem + 6.5vw, 4.75rem);
  --text-title: clamp(1.0625rem, 1rem + 0.4vw, 1.25rem);
  --text-body: 1.0625rem;
  --text-small: 0.9375rem;
  --text-micro: 0.8125rem;
}

/* Dark theme --------------------------------------------------------------
   app.js writes data-theme="light" or "dark" on the html element from the
   saved choice, or from the system when nothing is saved. Only the tokens
   change here, so every rule below keeps working unchanged. */

html[data-theme="dark"] {
  color-scheme: dark;

  --paper: #101713;
  --paper-line: rgba(140, 200, 165, 0.05);
  --glow: rgba(208, 138, 58, 0.1);
  --surface: #17201b;
  --surface-soft: #141c17;
  --ink: #e9ede6;
  --ink-soft: #b4beb5;
  --ink-faint: #98a39b;
  --line: #2a352d;
  --line-strong: #3b473e;
  --line-ui: #7f8d83;

  --green: #4fa377;
  --green-deep: #74c79d;
  --green-wash: rgba(79, 163, 119, 0.16);
  --green-edge: rgba(79, 163, 119, 0.45);

  --accent: #d08a3a;
  --accent-deep: #e6a75c;
  --accent-wash: rgba(208, 138, 58, 0.2);

  --danger: #e59279;
  --danger-wash: rgba(229, 146, 121, 0.14);
  --danger-edge: rgba(229, 146, 121, 0.42);

  --on-solid: #0e1512;

  --focus: #eef3ea;
  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.4), 0 16px 30px -24px rgba(0, 0, 0, 0.9);
  --shadow-button: 0 1px 2px rgba(0, 0, 0, 0.45);
  --shadow-button-hover: 0 4px 14px -6px rgba(0, 0, 0, 0.8);
}

/* Base ------------------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font);
  font-size: var(--text-body);
  line-height: 1.5;
  color: var(--ink);
  background-color: var(--paper);
  /* Graph paper: the day grid this app is made of, drawn faintly under
     everything. The sheet and its lines are tokens, so the whole page turns
     over with the theme switch. */
  background-image:
    linear-gradient(var(--paper-line) 1px, transparent 1px),
    linear-gradient(90deg, var(--paper-line) 1px, transparent 1px),
    radial-gradient(120% 55% at 50% -8%, var(--glow), transparent 72%);
  background-size: 28px 28px, 28px 28px, 100% 100%;
  background-repeat: repeat, repeat, no-repeat;
}

h1,
h2,
p {
  margin: 0;
}

.section-title {
  margin-bottom: 0.5rem;
  font-size: var(--text-title);
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

/* Links sit on the paper as words, so they answer on hover, on press and on
   focus with the same three states the buttons use. */
a {
  color: var(--green-deep);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: color 150ms ease, text-decoration-color 150ms ease;
}

a:hover {
  color: var(--accent-deep);
  text-decoration-thickness: 2px;
  text-decoration-color: var(--accent);
}

a:active {
  color: var(--ink);
  text-decoration-color: var(--ink);
}

::selection {
  color: var(--ink);
  background: var(--green-wash);
}

/* Focus ------------------------------------------------------------------
   One visible ring for every control, in the ink of the current theme. */

a:focus-visible,
button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.habit-tick:focus-visible {
  outline-offset: 3px;
}

/* Page frame ------------------------------------------------------------- */

.page {
  width: min(100% - 2.25rem, 40rem);
  margin-inline: auto;
  padding-block: clamp(1.75rem, 5vw, 3rem) 2.5rem;
  display: grid;
  gap: clamp(1.5rem, 4vw, 2.25rem);
}

/* The masthead holds the day and the theme switch side by side. */
.masthead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  padding-bottom: clamp(0.75rem, 2vw, 1.25rem);
  border-bottom: 1px solid var(--line-strong);
}

/* The day itself, the largest thing on the screen. */
.today {
  flex: 1 1 12rem;
  font-size: var(--text-display);
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 0.98;
  font-variant-numeric: tabular-nums;
  text-wrap: balance;
}

/* Theme switch -----------------------------------------------------------
   app.js puts this button in the masthead and writes its label, so the rule
   below both makes it part of the masthead and answers its three states. */

.theme-toggle {
  flex: 0 0 auto;
  padding: 0.45rem 0.95rem;
  font: inherit;
  font-size: var(--text-small);
  font-weight: 600;
  letter-spacing: -0.005em;
  white-space: nowrap;
  color: var(--ink-soft);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  cursor: pointer;
  box-shadow: var(--shadow-button);
  transition: color 150ms ease, background-color 150ms ease, border-color 150ms ease,
    transform 120ms ease, box-shadow 150ms ease;
}

.theme-toggle:hover {
  color: var(--ink);
  background: var(--surface-soft);
  border-color: var(--line-ui);
}

.theme-toggle:active {
  transform: translateY(1px);
  box-shadow: none;
}

/* Pressed means the dark theme is on, so the switch shows that state. */
.theme-toggle[aria-pressed="true"] {
  color: var(--ink);
  background: var(--green-wash);
  border-color: var(--green-edge);
}

.theme-toggle[aria-pressed="true"]:hover {
  background: var(--green-wash);
  border-color: var(--green);
}

.board {
  display: grid;
  gap: clamp(1.5rem, 4vw, 2.25rem);
}

/* Panels ----------------------------------------------------------------- */

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: clamp(1rem, 3.5vw, 1.5rem);
  scroll-margin-top: 1.5rem;
}

/* The habit list is the main object, so it keeps the card and its shadow. */
.panel.habits {
  border-color: var(--line-strong);
  box-shadow: var(--shadow-card);
}

/* Streaks are a quiet, dense list of lines sitting straight on the paper. */
.panel.streaks {
  padding: 0 0.25rem;
  background: none;
  border: 0;
  border-radius: 0;
}

/* The form is a distinct block with a field to fill in. */
.panel.add {
  background: var(--surface-soft);
  border-color: var(--line-strong);
}

/* Habit list ------------------------------------------------------------- */

.habit-list {
  display: grid;
  gap: 0.625rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.habit-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  column-gap: clamp(0.75rem, 3vw, 1.125rem);
  padding: 0.75rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  transition: background-color 150ms ease, border-color 150ms ease;
}

.habit-item:hover {
  border-color: var(--line-strong);
}

.habit-item:focus-within {
  border-color: var(--line-ui);
}

/* Ticked today: the whole row turns the colour of a finished day. */
.habit-item.is-ticked {
  background: var(--green-wash);
  border-color: var(--green-edge);
}

/* The daily tick box. The check inside the inline SVG keeps the colour of the
   box, so it is invisible until the habit is ticked. */
.habit-tick {
  display: inline-grid;
  place-items: center;
  width: clamp(2.75rem, 10vw, 3.25rem);
  height: clamp(2.75rem, 10vw, 3.25rem);
  padding: 0;
  color: transparent;
  background: var(--surface);
  border: 2px solid var(--line-ui);
  border-radius: 12px;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease,
    transform 120ms ease;
}

.habit-tick:hover {
  background: var(--green-wash);
  border-color: var(--green);
}

.habit-tick:active {
  background: var(--green-wash);
  border-color: var(--green-deep);
  transform: translateY(1px);
}

.habit-tick[aria-pressed="true"] {
  color: var(--on-solid);
  background: var(--green);
  border-color: var(--green);
}

.habit-tick[aria-pressed="true"]:hover {
  background: var(--green-deep);
  border-color: var(--green-deep);
}

.habit-tick[aria-pressed="true"]:active {
  background: var(--green-deep);
  border-color: var(--green-deep);
}

.tick-mark {
  display: block;
  width: 1.375rem;
  height: 1.375rem;
}

.habit-name {
  min-width: 0;
  font-size: var(--text-body);
  font-weight: 550;
  letter-spacing: -0.01em;
  overflow-wrap: break-word;
}

/* Streak badge in each row: quiet while the habit waits, solid clay once the
   day is ticked, because the streak is the result of the tick. */
.habit-streak {
  padding: 0.3rem 0.6rem;
  font-size: var(--text-micro);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--ink-faint);
  background: var(--surface-soft);
  border: 1px solid var(--line);
  border-radius: 999px;
}

.habit-item.is-ticked .habit-streak {
  color: var(--on-solid);
  background: var(--accent);
  border-color: var(--accent);
}

.habit-remove {
  padding: 0.35rem 0.5rem;
  font: inherit;
  font-size: var(--text-micro);
  font-weight: 600;
  color: var(--ink-faint);
  background: none;
  border: 1px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: color 150ms ease, background-color 150ms ease, border-color 150ms ease,
    transform 120ms ease;
}

.habit-remove:hover {
  color: var(--danger);
  background: var(--danger-wash);
  border-color: var(--danger-edge);
}

.habit-remove:active {
  color: var(--danger);
  background: var(--danger-wash);
  transform: translateY(1px);
}

/* Empty list ------------------------------------------------------------- */

.empty-note {
  margin: 0;
  padding: 0.9rem 1rem;
  font-size: var(--text-small);
  color: var(--ink-soft);
  background: var(--surface-soft);
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-sm);
}

.empty-note[hidden] {
  display: none;
}

/* Streak summary --------------------------------------------------------- */

.streak-note {
  margin-bottom: 0.35rem;
  font-size: var(--text-small);
  color: var(--ink-soft);
}

.streak-summary {
  display: grid;
}

.streak-line {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 1rem;
  padding: 0.6rem 0.15rem;
  font-size: var(--text-small);
  border-bottom: 1px solid var(--line);
}

.streak-line:last-child {
  border-bottom: 0;
}

.streak-name {
  min-width: 0;
  color: var(--ink-soft);
  overflow-wrap: break-word;
}

.streak-value {
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--ink-faint);
}

.streak-line.has-streak .streak-name {
  color: var(--ink);
  font-weight: 550;
}

.streak-line.has-streak .streak-value {
  padding: 0.15rem 0.55rem;
  color: var(--accent-deep);
  background: var(--accent-wash);
  border-radius: 999px;
}

/* Add form --------------------------------------------------------------- */

.habit-form {
  display: grid;
  gap: 0.5rem;
}

.field-label {
  font-size: var(--text-small);
  font-weight: 650;
  letter-spacing: -0.005em;
}

.field-input {
  width: 100%;
  min-width: 0;
  padding: 0.85rem 1rem;
  font: inherit;
  font-size: var(--text-body);
  color: var(--ink);
  background: var(--surface);
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius-sm);
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.field-input:hover {
  border-color: var(--line-ui);
}

.field-input:focus,
.field-input:focus-visible {
  outline: none;
  border-color: var(--green);
  box-shadow: 0 0 0 3px var(--green-wash);
}

.field-hint {
  font-size: var(--text-small);
  line-height: 1.45;
  color: var(--ink-soft);
}

.add-button {
  justify-self: start;
  margin-top: 0.25rem;
  padding: 0.8rem 1.4rem;
  font: inherit;
  font-size: var(--text-body);
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--on-solid);
  background: var(--accent);
  border: 1.5px solid var(--accent);
  border-radius: 12px;
  cursor: pointer;
  box-shadow: var(--shadow-button);
  transition: background-color 150ms ease, border-color 150ms ease, transform 120ms ease,
    box-shadow 150ms ease;
}

.add-button:hover {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
  box-shadow: var(--shadow-button-hover);
}

.add-button:active {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
  transform: translateY(1px);
  box-shadow: none;
}

/* Footer and notices ----------------------------------------------------- */

.footer {
  max-width: 34rem;
  padding-top: 1rem;
  font-size: var(--text-small);
  line-height: 1.6;
  color: var(--ink-soft);
  border-top: 1px solid var(--line-strong);
}

.storage-warning {
  margin-bottom: 0.75rem;
  padding: 0.8rem 1rem;
  font-size: var(--text-small);
  color: var(--danger);
  background: var(--danger-wash);
  border: 1px solid var(--danger-edge);
  border-radius: var(--radius-sm);
}

.notice {
  width: min(100% - 2.25rem, 40rem);
  margin: 1.5rem auto 0;
  padding: 0.9rem 1rem;
  font-size: var(--text-small);
  color: var(--danger);
  background: var(--danger-wash);
  border: 1px solid var(--danger-edge);
  border-radius: var(--radius-sm);
}

/* Skip link and screen reader text --------------------------------------- */

.skip-link {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 10;
  padding: 0.6rem 1rem;
  font-size: var(--text-small);
  font-weight: 650;
  color: var(--paper);
  background: var(--ink);
  border-radius: var(--radius-sm);
  text-decoration: none;
  transform: translateY(-200%);
  transition: transform 150ms ease, background-color 150ms ease, color 150ms ease;
}

.skip-link:hover,
.skip-link:focus,
.skip-link:focus-visible {
  transform: none;
}

.skip-link:hover {
  color: var(--on-solid);
  background: var(--green-deep);
}

.skip-link:active {
  color: var(--on-solid);
  background: var(--green-deep);
}

.skip-link:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Phone layout -----------------------------------------------------------
   The switch moves to the top right, the day takes the full width under it,
   and every habit row recomposes into a tick box beside a name, with the
   streak badge and the remove action on a second line. The action stretches
   so it sits within reach of a thumb. */

@media (max-width: 34rem) {
  :root {
    --text-display: clamp(2.75rem, 13vw, 3.5rem);
  }

  .page {
    width: 100%;
    padding-inline: 1rem;
    padding-block: 1.25rem 2rem;
    gap: 1.5rem;
  }

  .masthead {
    align-items: center;
    gap: 0.75rem;
  }

  .theme-toggle {
    order: 1;
    margin-left: auto;
  }

  .today {
    order: 2;
    flex-basis: 100%;
  }

  .board {
    gap: 1.5rem;
  }

  .panel {
    padding: 1rem;
    border-radius: var(--radius-sm);
  }

  .panel.streaks {
    padding: 0;
  }

  .habit-item {
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-areas:
      "tick name"
      "tick streak";
    column-gap: 0.75rem;
    row-gap: 0.5rem;
  }

  .habit-tick {
    grid-area: tick;
    align-self: center;
  }

  .habit-name {
    grid-area: name;
  }

  .habit-streak {
    grid-area: streak;
    justify-self: start;
  }

  .habit-remove {
    grid-column: 2;
    justify-self: end;
  }

  .add-button {
    justify-self: stretch;
    text-align: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms;
    animation-duration: 0.01ms;
  }
}
